// Calls made while the module mounts wait for the local session token instead of failing with 401.
let sessionReady;const session=new Promise(r=>sessionReady=r);
// A 401 is answered before the request is handled, so one retry after reconnecting cannot repeat a change.
const reconnect=sessionRecovery({t:pick,setToken:token=>{state.token=token;}});
async function api(path,data,method='POST',retry=true) {if(!state.token)await session;const response=await fetch(path,{method,headers:{Authorization:'Bearer '+state.token,...(data===undefined?{}:{'Content-Type':'application/json'})},...(data===undefined?{}:{body:JSON.stringify(data)})});if(response.status===401&&retry){await reconnect();return api(path,data,method,false);}if(!response.ok){const e=(await response.json()).error;throw Object.assign(new Error(e.message),e);}return response;}
async function json(path,data,method){return (await api(path,data,method)).json();}
function message(text,error=false){$('#message').textContent=text;$('#message').classList.toggle('error',error);}
function error(e){message(e.message,true);}
function status(){const p=state.project;$('#emptyCanvas').hidden=!!p;$('#frameSpace').hidden=!p;$('#inspectorToggle').disabled=!p;$('#previousScene').disabled=!p||p.plan.scenes[0].id===state.active;$('#nextScene').disabled=!p||p.plan.scenes.at(-1).id===state.active;$('#workbenchWatch').disabled=!state.render||!state.measured;$('#save').disabled=!p||!state.dirty||state.saving||!!state.drafts.size;$('#exportHTML').disabled=!p||state.saving||!state.measured||!!state.drafts.size||(!!p?.extensions.deckweftWorkbench&&!workbench?.ready());$('#undo').disabled=!state.undo.length;$('#redo').disabled=!state.redo.length;$('#backup').disabled=!p;$('#history').disabled=!p;$('#fit').textContent=!p?'':state.drafts.size?t('visual.main.unappliedFieldEditsNeedRepair'):state.measured?t('visual.main.fontsImagesAndDomLayoutMeasured'):t('visual.main.renderingAndMeasuring');$('#resetDraft').hidden=!state.drafts.size;$('#useInteractionOpening').disabled=!state.measured||!!state.drafts.size;author?.status();author?.drawControls();}
function changed(fn,{fields=false}={}) {if(!state.project)return;const before=structuredClone(state.project);fn();if(JSON.stringify(before)===JSON.stringify(state.project))return;invalidateCandidates();state.undo.push(before);if(state.undo.length>60)state.undo.shift();state.redo=[];state.counter++;state.dirty=true;state.measured=false;drawScenes();if(fields)drawEditor();status();schedulePreview();message(t('visual.main.unsavedChanges'));return true;}
function moveHistory(redo=false){invalidateCandidates();const from=redo?state.redo:state.undo,to=redo?state.undo:state.redo;if(!from.length)return;const rev=state.project.revision;to.push(structuredClone(state.project));state.project=from.pop();state.project.revision=rev;state.active=state.project.plan.scenes.some(s=>s.id===state.active)?state.active:state.project.plan.scenes[0].id;state.counter++;state.dirty=true;draw();schedulePreview();}
