  const id=holder.closest('[data-scene]').dataset.scene;
  if(!state.render){holder.replaceChildren();continue;}
  const url=state.render.artifactUrl+'?thumbnail='+encodeURIComponent(id);
  let frame=holder.querySelector('iframe');
  if(!frame||frame.getAttribute('src')!==url){frame=document.createElement('iframe');frame.src=url;frame.title=t('visual.main.pagePreview')+' '+id;frame.setAttribute('sandbox','');frame.tabIndex=-1;frame.loading='lazy';holder.replaceChildren(frame);}
