 const image=p.document.blocks.find(b=>s.blockIds.includes(b.id)&&b.type==='image'),crop=s.crops?.find(c=>c.blockId===image?.id)||{x:0,y:0,width:1,height:1};$('#cropFields').innerHTML=image?`<h2>${x(t('visual.main.imageCrop'))}</h2><div class="crop-grid">${['x','y','width','height'].map(k=>`<label>${k}<input type="number" min="0" max="1" step="0.01" value="${crop[k]}" data-crop="${k}" data-image="${image.id}" ${imageLocked(image.id)?'disabled':''}></label>`).join('')}</div>`:'';
