function scale(){const width=Number($('#viewport').value),available=$('#frameSpace').clientWidth,height=Math.ceil(state.fit?.checks?.find(c=>c.sceneId===state.active)?.height||900),heightLimit=innerWidth>1000&&$('#expandCanvas').getAttribute('aria-pressed')!=='true'?Math.max(420,innerHeight-480):Infinity,s=Math.min(1,available/width,heightLimit/height);$('#preview').style.width=width+'px';$('#preview').style.height=height+'px';$('#preview').style.transform=`scale(${s})`;$('#preview').style.position='absolute';$('#preview').style.left=Math.max(0,(available-width*s)/2)+'px';$('#frameSpace').style.height=Math.ceil(height*s)+'px';}
new ResizeObserver(()=>{scale();thumbnails();}).observe($('#frameSpace'));$('#viewport').onchange=()=>{state.measured=false;scale();status();};
function schedulePreview(){clearTimeout(previewTimer);const run=++sequence;state.render=null;state.fit=null;state.measured=false;status();thumbnails();if(state.drafts.size){$('#preview').removeAttribute('src');return;}previewTimer=setTimeout(async()=>{const counter=state.counter;try{const r=await json('/api/visual/preview',{project:state.project});if(run!==sequence||counter!==state.counter)return;state.render=r;thumbnailHeights.clear();thumbnails();$('#preview').src=r.artifactUrl+'#scene='+encodeURIComponent(state.active);scale();}catch(e){if(run===sequence){error(e);$('#fit').textContent=t('visual.main.previewNeedsRepairYourEditsRemain');}}},200);}
addEventListener('message',async e=>{if(e.source===$('#preview').contentWindow&&e.data?.type==='deckweft:scene'&&e.data.renderHash===state.render?.renderHash){if(e.data.sceneId!==state.active)selectScene(e.data.sceneId);return;}if(e.source===$('#preview').contentWindow&&e.data?.type==='deckweft:web-error'&&e.data.renderHash===state.render?.renderHash){state.measured=false;status();error(new Error(e.data.message));return;}if(e.source!==$('#preview').contentWindow||e.data?.type!=='deckweft:web-fit'||!state.render||e.data.fit?.renderHash!==state.render.renderHash)return;const ticket=state.render.ticket;state.fit=e.data.fit;if(state.fit.viewport.width===1440){for(const c of state.fit.checks)thumbnailHeights.set(c.sceneId,c.height);thumbnails();}scale();try{if(!e.data.fit.ok)throw new Error(t('visual.main.someRenderedContentDoesNotFit'));await json('/api/visual/measure',{ticket,fit:e.data.fit});if(state.render?.ticket!==ticket)return;state.measured=true;status();}catch(err){error(err);}});
async function save(){if(!state.project||state.saving||state.drafts.size)return false;reconnect.offerAgain();state.saving=true;status();const snapshot=structuredClone(state.project),counter=state.counter;try{const {project,historyUsage}=await json('/api/visual/projects/'+snapshot.id,{project:snapshot,expectedRevision:snapshot.revision.number},'PUT');if(state.project.id===snapshot.id){state.project.revision=project.revision;invalidateCandidates();if(counter===state.counter)state.dirty=false;}await libraries();schedulePreview();message([state.dirty?t('visual.main.newerEditsRemainUnsaved'):t('visual.main.savedOnThisComputer'),historyCapacityNote(historyUsage,pick)].filter(Boolean).join(' · '));return true;}catch(e){if(e.code==='REVISION_CONFLICT'){try{if(await saveCopy())return true;}catch(copyError){error(copyError);return false;}}error(e);return false;}finally{state.saving=false;status();}}
// After a 409 the author may keep the draft as a new document through the import-as-copy route; the newer revision stays untouched.
async function saveCopy(){if(!await askSaveCopy(pick))return false;const active=state.active,{project}=await json('/api/visual/import',{project:structuredClone(state.project)});activate(project);selectScene(active);await libraries();message(t('visual.main.savedAsASeparateCopyThe'));return true;}
async function leave(){return !state.dirty&&!state.drafts.size||confirm(t('visual.main.leaveTheseUnsavedEditsExportProject'));}
