function drawCandidates(){if(!candidateState)return;const i=state.project.plan.scenes.findIndex(s=>s.id===state.active);for(const [k,set]of candidateState.sets.entries()){const card=$(`[data-candidate="${k}"]`);if(!card)continue;const descriptor=set.scenes[i],label=candidateState.families[descriptor.family]?.variants.find(v=>v[0]===descriptor.id);card.querySelector('h3').textContent=(k+1)+' · '+(label?pick(label[1],label[2]):descriptor.id);const fit=set.fits?.[i];card.querySelector('.candidate-fit').textContent=fit?(fit.ok?t('visual.main.fits')+Math.ceil(fit.height)+'px'+(fit.features?' · '+t('visual.main.density')+Math.round(fit.features.density*100)+'% · '+t('visual.main.image')+Math.round(fit.features.imageRatio*100)+'%':''):fit.reasons.join(' · ')):t('visual.main.measuringFontsAndLayout');card.querySelector('[data-select-candidate]').disabled=!fit?.ok;card.querySelector('iframe').contentWindow?.postMessage({type:'deckweft:select',sceneId:state.active},'*');}$('#rhythm').disabled=!candidateState.sets.every(s=>s.fits);scaleCandidates();}
